#include "TradeRouteSpecComponent.h"

UTradeRouteSpecComponent::UTradeRouteSpecComponent(const FObjectInitializer& ObjectInitializer)
	: Super(ObjectInitializer)
{
	CommoditiesAllowed = { TEXT("water_ice"), TEXT("rations"), TEXT("machine_parts") };
	EnemyFactions = { TEXT("faction_pirate_syndicate") };
}

float UTradeRouteSpecComponent::EvaluateRouteProfit() const
{
	const float KgProfit = (SellPricePerKg - BuyPricePerKg) * QuantityKg;
	const float RationProfit = (SellPricePerRation - BuyPricePerRation) * QuantityRations;
	const float UnitProfit = (SellPricePerUnit - BuyPricePerUnit) * QuantityUnits;
	const float FuelCost = FuelCostLiters + (bRequiresQuantumDrive ? FuelCostPerJumpLiters : 0.0f);
	return KgProfit + RationProfit + UnitProfit - FuelCost;
}

bool UTradeRouteSpecComponent::RollInterdiction(float Random01) const
{
	return Random01 < FMath::Clamp(InterdictionChance, 0.0f, 1.0f);
}

bool UTradeRouteSpecComponent::IsCommodityAllowed(const FString& Commodity) const
{
	return CommoditiesAllowed.Contains(Commodity) || Commodity == RequiredCommodity;
}

bool UTradeRouteSpecComponent::ValidateSpec() const
{
	// every spec value participates: a route must name real endpoints, carry
	// positive quantities, and price both sides of every unit it hauls.
	const bool bEndpoints = !OriginStation.IsEmpty() && !DestinationStation.IsEmpty() && !Destination.IsEmpty();
	const bool bQuantities = QuantityKg >= 0.0f && QuantityRations >= 0.0f && QuantityUnits >= 0.0f;
	const bool bTravel = TravelTimeSeconds > 0.0f && FuelCostLiters >= 0.0f;
	const bool bRisk = !DangerLevel.IsEmpty() && !PenaltyFailed.IsEmpty() && EnemyFactions.Num() >= 0;
	return bEndpoints && bQuantities && bTravel && bRisk;
}
